    r = int(assign.get('root_power', 0))
    q = int(assign.get('reciprocal_power', 0))
except Exception:
    # Invalid assignments
    return (False, None)
if N < 1 or r < 3 or q not in (1, 2):
    # Domain constraints not met
    return (False, None)
D = 1 << r
from fractions import Fraction
S = Fraction(0, 1)
distinct = 0
m = 1
last_R = None
last_L = None
processed_any = False
while True:
    L = ((2*m - 1)**r) // D + 1
    if L > N:
        break
    R = ((2*m + 1)**r) // D
    c = min(N, R) - L + 1
    if c > 0:
        S += Fraction(c, (m ** q))
        distinct += 1
        processed_any = True
        last_R = R
        last_L = L
    m += 1
if not processed_any:
    # No terms aggregated: invalid
    return (False, None)
# Enforce difficulty: at least 10 distinct f(n) values appear
if distinct < 10:
    return (False, None)
# Enforce that the last interval was partial (i.e., N cuts an interval), not ending exactly at R
# If N == last_R then the last interval was complete; we reject to avoid trivial boundary cases.
if last_R is not None and N == last_R:
    return (False, None)
# Produce final answer as P + Q where S = P/Q in lowest terms
P = S.numerator
Q = S.denominator
